public boolean shouldPrintMessage(int timestamp, String message) {
    // Check if the message is empty
    if (message.isEmpty()) {
        return false;
    }

    // Check if the timestamp is negative
    if (timestamp < 0) {
        return false;
    }

    // Check if the timestamp is greater than the current time
    if (timestamp > System.currentTimeMillis() / 1000) {
        return false;
    }

    // Check if the message is a valid format
    if (!message.matches("[a-zA-Z0-9 ]+")) {
        return false;
    }

    return true;
}
