private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Check if the current byte is a continuation byte
    if ((bb.get(i) & 0xC0) == 0x80) {
        // If so, it is an invalid continuation byte
        throw new IllegalArgumentException("Invalid continuation byte");
    }

    // Get the number of bytes needed to represent the character
    int numBytes = (bb.get(i) & 0xFF) >> 4;

    // Check if the number of bytes is valid
    if (numBytes < 1 || numBytes > 4) {
        // If not, it is an invalid character
        throw new IllegalArgumentException("Invalid character");
    }

    // Get the character value
    int value = 0;
    for (int j = 0; j < numBytes; j++) {
        // Get the next byte
        int byteValue = bb.get(i + j) & 0xFF;

        // Check if the byte is a continuation byte
        if ((byteValue & 0xC0) != 0x80) {
            // If not, it is an invalid continuation byte
            throw new IllegalArgumentException("Invalid continuation byte");
        }

        // Shift the byte value and add it to the character value
        value = (value << 6) | (byteValue & 0x3F);
    }

    // Append the character to the string buffer
    sb.append((char) value);

    // Return the index to the next unchecked character in the string to decode
    return i + numBytes;
}
