public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Initialize the mapping
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>();

    // Iterate over the vertices in the graph
    for (V vertex : graph.getVertices()) {
        // Add the vertex to the mapping
        mapping.addVertex(vertex, vertex);
    }

    // Iterate over the edges in the graph
    for (E edge : graph.getEdges()) {
        // Get the source and target vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the edge to the mapping
        mapping.addEdge(source, target, edge);
    }

    return mapping;
}
