private static void forceDeleteDirectory(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }
    if (!directory.isDirectory()) {
        throw new IOException("File " + directory + " is not a directory");
    }
    for (File file : directory.listFiles()) {
        forceDelete(file);
    }
    if (!directory.delete()) {
        throw new IOException("Failed to delete directory " + directory);
    }
}

private static void forceDeleteFile(File file) throws IOException {
    if (!file.exists()) {
        return;
    }
    if (!file.isFile()) {
        throw new IOException("File " + file + " is not a file");
    }
    if (!file.delete()) {
        throw new IOException("Failed to delete file " + file);
    }
}
