public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty inputs
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: path or relativePath cannot be null or empty");
    }

    // Split the path and relative path into individual components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Initialize the result path with the first component of the path
    String resultPath = pathComponents[0];

    // Iterate over the remaining components of the relative path
    for (int i = 1; i < relativePathComponents.length; i++) {
        // If the current component is "..", remove the last component of the result path
        if (relativePathComponents[i].equals("..")) {
            if (resultPath.endsWith("/")) {
                resultPath = resultPath.substring(0, resultPath.length() - 1);
            }
            int lastSlashIndex = resultPath.lastIndexOf('/');
            if (lastSlashIndex == -1) {
                throw new IllegalArgumentException("Invalid relative path: too many '..' components");
            }
            resultPath = resultPath.substring(0, lastSlashIndex);
        }
        // Otherwise, append the current component to the result path
        else {
            resultPath += "/" + relativePathComponents[i];
        }
    }

    return resultPath;
}

