        return -1;
    }
    int lastSeparator = indexOfLastSeparator(filename);
    if (lastSeparator == -1) {
        return -1;
    }
    int firstSeparator = filename.indexOf('.', lastSeparator + 1);
    if (firstSeparator == -1 || firstSeparator < lastSeparator) {
        return -1;
    }
    return firstSeparator;
}
